'use strict'; // v4 uses LuCI network statistics only
'require baseclass';
'require ui';

return baseclass.extend({
	callError(title, err) {
		ui.addNotification(title, E('p', {}, err?.message || String(err)), 'error');
	},
	resultText(result) {
		return result?.output || result?.error || _('No response');
	},
	panel(title, body) {
		return E('section', { 'class': 'm5-panel' }, [ E('h3', {}, title), body ]);
	},
	metric(label, value, id) {
		return E('div', { 'class': 'm5-metric' }, [ E('small', {}, label), E('strong', id ? { id } : {}, value || '-') ]);
	},
	extraStyle() {
		return E('style', {}, '.m5-page{max-width:1280px}.m5-dashboard{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(360px,.75fr);gap:1rem;align-items:stretch}.m5-dashboard>.m5-panel{margin:1rem 0;height:auto}.m5-dashboard .m5-hero{grid-template-columns:repeat(2,minmax(0,1fr))}.m5-dashboard .m5-hero .m5-metric:first-child{grid-row:auto;grid-column:span 2;min-height:4.5rem}.m5-gauges{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;align-items:center;height:calc(100% - 2.5rem)}.m5-gauge{--gauge-angle:0deg;position:relative;aspect-ratio:1.45/1;overflow:hidden;display:flex;align-items:flex-end;justify-content:center}.m5-gauge:before,.m5-gauge-progress{position:absolute;width:92%;aspect-ratio:1;border-radius:50%;top:10%;left:4%}.m5-gauge:before{content:"";background:conic-gradient(from 225deg,var(--border-color-medium,#465064) 0 270deg,transparent 270deg)}.m5-gauge-progress{display:block;background:conic-gradient(from 225deg,#2587ff 0deg,#25b8ef 55deg,#34c759 130deg,#ffd60a 195deg,#ff453a 270deg,transparent 270deg);-webkit-mask:conic-gradient(from 225deg,#000 0deg var(--gauge-angle),transparent var(--gauge-angle) 360deg);mask:conic-gradient(from 225deg,#000 0deg var(--gauge-angle),transparent var(--gauge-angle) 360deg);transition:--gauge-angle .8s ease-out}.m5-gauge:after{content:"";position:absolute;width:67%;aspect-ratio:1;border-radius:50%;background:var(--background-color-high,#fff);top:22.5%;left:16.5%;z-index:2}.m5-gauge-face{position:relative;z-index:3;text-align:center;padding-bottom:8%;display:flex;flex-direction:column;align-items:center}.m5-gauge-face strong{font-size:1.45rem;line-height:1.2}.m5-gauge-face small{opacity:.68}.m5-gauge-icon{font-size:1.3rem;font-weight:800;color:#2d8cff}.m5-gauge-up .m5-gauge-icon{color:#34c759}.m5-band-grid{grid-template-columns:repeat(auto-fit,minmax(5.4rem,1fr));gap:.8rem}.m5-band span{padding:.85rem .4rem}.m5-form{grid-template-columns:10rem minmax(0,1fr);max-width:850px}.m5-lock-footer{display:flex;flex-wrap:wrap}.m5-lock-footer .btn{min-width:9rem}.m5-cell-table{table-layout:fixed;min-width:680px}.m5-cell-table th,.m5-cell-table td{white-space:nowrap}@media(max-width:1050px){.m5-dashboard{grid-template-columns:1fr}.m5-gauges{max-width:650px;margin:auto;width:100%}}@media(max-width:600px){.m5-gauges{grid-template-columns:1fr 1fr;gap:.35rem}.m5-gauge-face strong{font-size:1rem}.m5-dashboard .m5-hero{grid-template-columns:1fr}.m5-dashboard .m5-hero .m5-metric:first-child{grid-column:auto}.m5-form{grid-template-columns:1fr}.m5-lock-footer .btn{flex:1;min-width:8rem}}');
	},
	style() {
		return E('style', {}, '.m5-page{max-width:1150px;margin:0 auto}.m5-head{display:flex;justify-content:space-between;align-items:center;gap:1rem}.m5-live{color:#29934a;font-weight:600}.m5-panel{padding:1.15rem 1.3rem;margin:1rem 0;border:1px solid var(--border-color-medium,#d8dee6);border-radius:.85rem;background:var(--background-color-high,#fff);box-shadow:0 2px 10px rgba(0,0,0,.035)}.m5-panel h3{margin:0 0 1rem}.m5-grid{display:grid;grid-template-columns:repeat(4,minmax(9em,1fr));gap:.7rem}.m5-metric{padding:.85rem;background:var(--background-color-medium,#f4f5f6);border:1px solid var(--border-color-low,#e5e9ee);border-radius:.65rem;overflow-wrap:anywhere}.m5-metric small{display:block;opacity:.68;margin-bottom:.3rem}.m5-metric strong{white-space:pre-wrap}.m5-hero{display:grid;grid-template-columns:1.25fr repeat(4,1fr);gap:.75rem}.m5-hero .m5-metric:first-child{grid-row:span 2;display:flex;flex-direction:column;justify-content:center}.m5-hero .m5-metric:first-child strong{font-size:1.7rem}.m5-signal-good{color:#29934a}.m5-signal-mid{color:#b7791f}.m5-signal-poor{color:#c2412d}.m5-cell-table{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border-radius:.6rem}.m5-cell-table th{background:#2d65a0;color:#fff}.m5-cell-table th,.m5-cell-table td{padding:.7rem;text-align:center;border-bottom:1px solid var(--border-color-low,#e5e9ee)}.m5-cell-table tbody tr{cursor:pointer}.m5-cell-table tbody tr:hover{background:var(--background-color-medium,#f4f5f6)}.m5-serving{font-weight:700;color:#29934a}.m5-tabs{display:flex;padding:.3rem;border:1px solid var(--border-color-medium,#d8dee6);border-radius:999px;margin:1rem 0;background:var(--background-color-low,#f7f8fa)}.m5-tabs button{flex:1;border:0!important;border-radius:999px!important;padding:.7rem!important;background:transparent!important}.m5-tabs button.active{background:var(--background-color-high,#fff)!important;color:#1677c8!important;font-weight:700;box-shadow:0 1px 7px rgba(0,0,0,.12)}.m5-band-grid{display:grid;grid-template-columns:repeat(6,minmax(4.5rem,1fr));gap:.65rem}.m5-band{position:relative}.m5-band input{position:absolute;opacity:0;pointer-events:none}.m5-band span{display:block;padding:.7rem .3rem;text-align:center;border:1px solid var(--border-color-medium,#ccd4de);border-radius:.6rem;font-weight:600;cursor:pointer}.m5-band input:checked+span{color:#fff;background:#2d65a0;border-color:#2d65a0}.m5-lock-pane[hidden]{display:none}.m5-lock-footer{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-top:1rem}.m5-lock-footer .btn{padding:.7rem}.m5-raw{display:block;white-space:pre-wrap;overflow:auto;max-height:25rem;padding:.8rem;background:#1e252b;color:#d7e0e5;border-radius:.45rem}.m5-actions{display:flex;flex-wrap:wrap;gap:.55rem}.m5-form{display:grid;grid-template-columns:minmax(9em,1fr) 2fr;gap:.7rem;align-items:center}.m5-form input,.m5-form textarea,.m5-form select{width:100%}.m5-note{opacity:.72}.m5-good{color:#29934a}@media(max-width:900px){.m5-hero{grid-template-columns:repeat(2,1fr)}.m5-hero .m5-metric:first-child{grid-row:auto;grid-column:span 2}.m5-band-grid{grid-template-columns:repeat(4,1fr)}}@media(max-width:750px){.m5-grid{grid-template-columns:repeat(2,1fr)}.m5-form{grid-template-columns:1fr}.m5-head{align-items:flex-start}.m5-cell-table{font-size:.85rem}.m5-cell-table th,.m5-cell-table td{padding:.5rem .25rem}.m5-band-grid{grid-template-columns:repeat(3,1fr)}}');
	}
});
